import{_ as a,a as t,c as i,ac as l}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse(`{"title":"第一册：英语初阶 · Lesson 71 He's awful!","description":"学习 一般过去时与 did，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 71 He's awful!","description":"学习 一般过去时与 did，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 一般过去时与 did，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 70 When were they there?","link":"/life/english/new-concept/book-1/unit-03/lesson-070"},"next":{"text":"第一册：英语初阶 · Lesson 72 When did you ...?","link":"/life/english/new-concept/book-1/unit-03/lesson-072"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 70 When were they there?","link":"/life/english/new-concept/book-1/unit-03/lesson-070"},"next":{"text":"第一册：英语初阶 · Lesson 72 When did you ...?","link":"/life/english/new-concept/book-1/unit-03/lesson-072"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-03/lesson-071.md","filePath":"life/english/new-concept/book-1/unit-03/lesson-071.md"}`),n={name:"life/english/new-concept/book-1/unit-03/lesson-071.md"};function o(d,e,s,r,h,c){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="第一册-英语初阶-·-lesson-71-he-s-awful" tabindex="-1">第一册：英语初阶 · Lesson 71 He&#39;s awful! <a class="header-anchor" href="#第一册-英语初阶-·-lesson-71-he-s-awful" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 71 He&#39;s awful!&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-03/overview">单元 3</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-072">配套课 Lesson 72</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>回忆过去发生的动作并询问时间 本课要掌握一般过去时与 did，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。先根据情境判断为什么要这样问或这样说，再看语言形式。</p><p>本课为情景学习；完成后进入相邻偶数课进行句型迁移。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>awful</td><td>/ˈɔːfl/</td><td>adj.</td><td>糟糕的</td><td>an awful noise</td></tr><tr><td>telephone</td><td>/ˈtelɪfəʊn/</td><td>v.</td><td>打电话</td><td>telephone a friend</td></tr><tr><td>answer</td><td>/ˈɑːnsə/</td><td>v.</td><td>回答；接听</td><td>answer a call</td></tr><tr><td>again</td><td>/əˈɡen/</td><td>adv.</td><td>再次</td><td>call again</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>did you call — 询问过去动作</li><li>last night — 昨夜，前面不加介词</li></ul><h2 id="语法讲解-一般过去时与-did" tabindex="-1">语法讲解：一般过去时与 did <a class="header-anchor" href="#语法讲解-一般过去时与-did" aria-label="Permalink to &quot;语法讲解：一般过去时与 did&quot;">​</a></h2><p>规则动词过去式一般加 ed；以 e 结尾加 d，以辅音字母加 y 结尾通常把 y 变 i 加 ed。否定和问句由 did 承担过去标记，后面用原形。I called 与 Did you call? 相互对应，不能写 Did you called?。过去动作是否重复由语境决定，一般过去时也能表达过去的习惯。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>She called the office twice yesterday.</p></blockquote><p>她昨天给办公室打了两次电话。</p><p>She called 是一般过去时肯定句；called 为规则过去式，twice 表次数，yesterday 表过去时间。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>did 后使用 finish，不使用 finished；疑问句已有过去标记。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“She called the office twice yesterday.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>She called the office twice yesterday. When did you finish the report?</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“回忆过去发生的动作并询问时间”写两至三句，再读给同伴听。至少使用一次一般过去时与 did，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>She called 是一般过去时肯定句；called 为规则过去式，twice 表次数，yesterday 表过去时间。 When 询问完成时间；did 承担过去标记，you 为主语，finish 恢复原形，the report 为宾语。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填过去式：She ___ (call) yesterday.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> called</p><p><strong>解析：</strong> 按本课规则判断：规则动词过去式一般加 ed；以 e 结尾加 d，以辅音字母加 y 结尾通常把 y 变 i 加 ed。否定和问句由 did 承担过去标记，后面用原形。I called 与 Did you call? 相互对应，不能写 Did you called?。过去动作是否重复由语境决定，一般过去时也能表达过去的习惯。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“她昨天给办公室打了两次电话。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She called the office twice yesterday.</p><p><strong>解析：</strong> She called 是一般过去时肯定句；called 为规则过去式，twice 表次数，yesterday 表过去时间。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：When did you finish the report?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 你什么时候完成了报告？</p><p><strong>解析：</strong> When 询问完成时间；did 承担过去标记，you 为主语，finish 恢复原形，the report 为宾语。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：一般过去时与 did。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-070">上一课</a> · <a href="/life/english/new-concept/book-1/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-072">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=a(n,[["render",o]]);export{p as __pageData,f as default};
